<script setup lang="ts">
import { onMounted, ref } from "vue";
import { http } from "@/utils/http";
type Check = { name: string; status: string; detail: string }; const checks = ref<Check[]>([]); const loading = ref(false); const error = ref(""); const refresh = ref("off"); const metricRange = ref("1h"); const lastChecked = ref("");
async function load() { loading.value = true; error.value = ""; try { const [live, ready] = await Promise.allSettled([http.get<any, any>("/health/live"), http.get<any, any>("/health/ready")]); checks.value = [{ name: "Application / API", status: live.status === "fulfilled" ? live.value?.status || "UP" : "DOWN", detail: "应用存活探针" }, { name: "PostgreSQL", status: ready.status === "fulfilled" ? ready.value?.status || "UP" : "DOWN", detail: "数据库就绪探针" }, ...["持久化 Storage Backend", "Cache", "Search / Index", "Scheduler / Worker Queue", "Plugin / Connector Runtime", "External Provider"].map(name => ({ name, status: "UNKNOWN", detail: "后端未提供该组件的健康探针" }))]; lastChecked.value = new Date().toLocaleString(); } catch (e: any) { error.value = e?.message || "健康检查失败"; } finally { loading.value = false; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">系统健康与告警</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">查看后端定义的健康状态和组件探针结果。</p></div><div class="flex gap-2"><el-tag>开发环境</el-tag><el-select v-model="refresh" class="w-32"><el-option label="自动刷新：关闭" value="off"/><el-option label="30 秒" value="30"/><el-option label="1 分钟" value="60"/><el-option label="5 分钟" value="300"/></el-select><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert :title="checks.some(item => item.status === 'DOWN') ? '后端报告异常' : '后端健康状态已返回'" :type="checks.some(item => item.status === 'DOWN') ? 'error' : 'success'" show-icon :closable="false" class="mb-2"/><div class="flex justify-between items-center mb-5 text-sm text-[var(--el-text-color-secondary)]"><span>整体状态由后端健康模型计算，前端不根据单个指标推导。</span><span>最近检查：{{ lastChecked || '—' }}</span></div><el-skeleton v-if="loading" :rows="8" animated/><div v-else class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4"><el-card v-for="item in checks" :key="item.name" shadow="never"><div class="flex justify-between"><span class="font-medium">{{ item.name }}</span><el-tag :type="item.status === 'UP' ? 'success' : item.status === 'UNKNOWN' ? 'info' : 'danger'">{{ item.status }}</el-tag></div><p class="text-sm text-[var(--el-text-color-secondary)] mt-3">{{ item.detail }}</p><div class="text-xs text-[var(--el-text-color-secondary)] mt-4">响应延迟：— · Incident：—</div><el-button link class="mt-2" disabled>查看详情</el-button></el-card><el-card shadow="never"><template #header><div class="flex justify-between"><span>资源指标</span><el-radio-group v-model="metricRange" size="small"><el-radio-button label="15m">15m</el-radio-button><el-radio-button label="1h">1h</el-radio-button><el-radio-button label="6h">6h</el-radio-button><el-radio-button label="24h">24h</el-radio-button><el-radio-button label="7d">7d</el-radio-button></el-radio-group></div></template><el-empty description="暂无 CPU、Memory、Heap、Disk、DB Pool、Queue Sample" :image-size="70"/><div class="text-xs text-[var(--el-text-color-secondary)]">单位与时间范围：{{ metricRange }}；缺失采样保持 Gap。</div></el-card><el-card shadow="never"><template #header>告警面板</template><el-table :data="[]"><el-table-column label="Severity"/><el-table-column label="Alert Name"/><el-table-column label="Component"/><el-table-column label="Opened Time"/><el-table-column label="State"/></el-table><el-empty description="暂无告警数据" :image-size="70"/></el-card></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mt-4"/></main></template>
